INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4872968', 'Battle of the Nobles', 'The Battle of the Nobles (Arabic: غزوة الأشراف, romanized: Ghazwat al-Ashrāf) was an important confrontation in the Berber Revolt in c. 740 AD. It resulted in a major Berber victory over the Arabs in banks of the Chelif River, near Chlef (Algeria).', 740, 12, NULL, NULL, NULL, NULL, 'month', 'December 740', 39, 'https://en.wikipedia.org/wiki/Battle_of_the_Nobles'),
  ('Q4870380', 'Battle of Bagdoura', 'The Battle of Bagdoura or Battle of Sebou was a decisive confrontation in the Berber Revolt in late 741 CE. It was a follow-up to the Battle of the Nobles the previous year, and resulted in a major Berber victory over the Umayyad Caliphate by the Sebou River (near modern Fes). The battle would permanently break the hold of the caliphate over the far western Maghreb (Modern day Morocco), and the resulting retreat of elite Syrian forces into Spain would have implications for the stability of al-Andalus.', 741, 10, NULL, NULL, NULL, NULL, 'month', 'October 741', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bagdoura'),
  ('Q4546456', '1033 Fez massacre', 'The 1033 Fez massacre was an event where, following their conquest of the city from the Maghrawa tribe, the forces of Abu''l Kamal Tamim, chief of the Banu Ifran tribe, perpetrated a massacre of Jews in Fes. David Corcos wrote that the Bani Ifran from near Salé attacked Fes, where they raped, pillaged, and killed 6,000 Jews.', 1033, NULL, NULL, NULL, NULL, NULL, 'year', '1033', 34, 'https://en.wikipedia.org/wiki/1033_Fez_massacre'),
  ('Q2888296', 'Conquest of Ceuta', 'Portuguese forces under the command of King John I conquered the North African city of Ceuta from the Marinid Sultanate on 21 August 1415. The city''s defenses fell under Portuguese control after a carefully prepared attack, and the successful capture of the city marked the beginning of the Portuguese Empire.', 1415, 8, 21, NULL, NULL, NULL, 'day', '21 August 1415', 57, 'https://en.wikipedia.org/wiki/Portuguese_conquest_of_Ceuta'),
  ('Q4872500', 'Battle of Tangier', 'The Battle of Tangier, sometimes referred to as the siege of Tangiers, and by the Portuguese, as the disaster of Tangier (Portuguese: Desastre de Tânger), refers to the attempt by a Portuguese expeditionary force to seize the Moroccan citadel of Tangier and its defeat by the armies of the Marinid Sultanate in 1437. The Portuguese expeditionary force, led by Prince Henry the Navigator, Duke of Viseu, set out from Portugal in August 1437, intending to seize a series of Moroccan coastal citadels.', 1437, 9, 13, 1437, 10, 19, 'day', '13 September 1437 – 19 October 1437', 43, 'https://en.wikipedia.org/wiki/Battle_of_Tangier_(1437)'),
  ('Q3411960', '1465 Fez revolt', 'The 1465 Fez revolt was a popular uprising in the Marinid capital of Fez against Sultan Abd al-Haqq II, the final ruler of the Marinid dynasty, and his Jewish vizier, Harun ibn Batash. The Marinid Sultanate faced a severe crisis in the mid-15th century, exacerbated by progressive Portuguese incursions into its territory.', 1465, NULL, NULL, 1472, NULL, NULL, 'year', '1465–1472', 34, 'https://en.wikipedia.org/wiki/1465_Fez_revolt'),
  ('Q5162432', 'Conquest of Asilah', 'The Portuguese conquest of Asilah (Arabic: أصيلة، أرزيلة; Portuguese: Arzila) was a campaign led by King Afonso V in modern Morocco from the Wattasids on 24 August 1471.', 1471, 8, 24, NULL, NULL, NULL, 'day', '24 August 1471', 41, 'https://en.wikipedia.org/wiki/Conquest_of_Asilah'),
  ('Q2887914', 'Battle of Azemmour', 'The Battle of Azemmour took place in Morocco, on 28 and 29 August 1513 between the Portuguese Empire and the Moroccan Wattasid dynasty. Azemmour, dependent on the King of Fes, even enjoying of great autonomy, paid vassalage to the king João II of Portugal since 1486.', 1513, 8, 28, 1513, 8, 29, 'day', '28 August 1513 – 29 August 1513', 39, 'https://en.wikipedia.org/wiki/Battle_of_Azemmour'),
  ('Q105162351', 'Capture of Fez', 'The Conquest of Fez or Capture of Fez took place in 1554 between the Algerian forces of Salah Rais and the ruler of the Saadi Sultanate, Mohammed ash-Sheikh. The battle took place on 7 January at Qudyat-al-Mahali, a suburb near Fez and occurred after Salah Reis’ two previous victories against the Saadians, one at Taza and another at the Sebou river.', 1554, 1, 7, NULL, NULL, NULL, 'day', '7 January 1554', 43, 'https://en.wikipedia.org/wiki/Capture_of_Fez_(1554)'),
  ('Q4117011', 'Battle of Wadi al-Laban', 'The Battle of Wadi al-Laban (Arabic: معركة وادي اللبن) occurred in March–April 1558 between Saadians and Ottoman Algerian forces under Hasan Pasha, the son of Hayreddin Barbarossa. It took place north of Fes, at Wadi al-Laban, an affluent of the Sebou River, one day north of Fes.', 1558, 4, 2, 1558, 4, 6, 'day', '2 April 1558 – 6 April 1558', 43, 'https://en.wikipedia.org/wiki/Battle_of_Wadi_al-Laban'),
  ('Q30745598', 'Capture of Fez', 'The Capture of Fez took place in 1576 at Fez, when forces operating from the Regency of Algiers supported the Saadian prince Abd al-Malik in securing the Saadian throne against his nephew and rival claimant, Muhammad al-Mutawakkil. This support was linked to a political arrangement in which Abd al-Malik publicly acknowledged Ottoman supremacy in political practice.', 1576, 3, NULL, NULL, NULL, NULL, 'month', 'March 1576', 45, 'https://en.wikipedia.org/wiki/Capture_of_Fez_(1576)'),
  ('Q1121532', 'Battle of Alcácer Quibir', 'The Battle of Alcácer Quibir (also known as "Battle of Three Kings" (Arabic: معركة الملوك الثلاثة) or "Battle of Wadi al-Makhazin" (Arabic: معركة وادي المخازن) in Morocco) was fought in northern Morocco, near the town of Ksar-el-Kebir (variant spellings: Ksar El Kebir, Alcácer-Quivir, Alcazarquivir, Alcassar, etc.) and Larache, on 4 August 1578. A Moroccan victory, the battle has been described as "the greatest military disaster the Portuguese ever suffered in the course of their overseas expansion." It marked an end to Portuguese attempts to reconquer territories it had lost in Morocco.', 1578, 8, 4, NULL, NULL, NULL, 'day', '4 August 1578', 67, 'https://en.wikipedia.org/wiki/Battle_of_Alc%C3%A1cer_Quibir'),
  ('Q21029691', 'Battle of Tangier', 'The Battle of Tangier, also known as the Battle of Jew''s Hill, took place between a detachment of the English Tangier Garrison under the command of governor of Tangier Lord Teviot by a Moroccan force commanded by Khadir Ghaïlan on 4 May 1664. Successfully ambushing the 500-strong English force, Ghaïlan''s men killed all but thirty of them, including Teviot.', 1664, 5, 4, NULL, NULL, NULL, 'day', '4 May 1664', 34, 'https://en.wikipedia.org/wiki/Battle_of_Tangier_(1664)'),
  ('Q3485921', 'Siege of Larache', 'The siege of Larache, in 1689, was undertaken by an army of Morocco under ''Alawid Sultan Ismail Ibn Sharif against the Spanish forces of Charles II, which had ruled the city for almost 80 years since its cession in 1610. After three months of siege, the defenders were forced to capitulate.', 1689, 8, NULL, 1689, 11, 11, 'month', 'August 1689 – 11 November 1689', 34, 'https://en.wikipedia.org/wiki/Siege_of_Larache_(1689)'),
  ('Q115809087', '1755 Meknes earthquake', 'The 1755 Meknes earthquake affected Morocco on 27 November 1755. The earthquake had a moment magnitude (Mw) estimated at between 6.5 and 7.0.', 1755, 11, 27, NULL, NULL, NULL, 'day', '27 November 1755', 39, 'https://en.wikipedia.org/wiki/1755_Meknes_earthquake'),
  ('Q2909607', 'Larache expedition', 'The Expedition of Larache occurred in June 1765 when French Navy Marines attempted to invade the Moroccan city of Larache following a bombardment of Salé and Rabat. It is an example of the sporadic failure of Western arms against local forces in colonial campaigns.', 1765, 6, NULL, NULL, NULL, NULL, 'month', 'June 1765', 34, 'https://en.wikipedia.org/wiki/Larache_expedition'),
  ('Q348998', 'Battle of Isly', 'The Battle of Isly (Arabic: معركة إيسلي) was fought on August 14, 1844, between France and Morocco, near the Isly River. French forces under Marshal Thomas Robert Bugeaud routed a much larger, but poorly organized, Moroccan force, mainly fighters from the tribes of Beni Snassen, but also from the Beni Angad and Beni Oukil; under Muhammad, son of the Sultan of Morocco, Abd al-Rahman.', 1844, 8, 14, NULL, NULL, NULL, 'day', '14 August 1844', 50, 'https://en.wikipedia.org/wiki/Battle_of_Isly'),
  ('Q3062439', 'Franco-Moroccan War', 'The Franco-Moroccan War (Arabic: الحرب الفرنسية المغربية, French: Guerre franco-marocaine) was fought between the Kingdom of France and the Sultanate of Morocco from 6 August to 10 September 1844. The principal cause of war was the retreat of Algerian resistance leader Abd al-Kader into Morocco following French victories over many of his tribal supporters during the French conquest of Algeria and the refusal of the Sultan of Morocco Moulay Abd al-Rahman to abandon the cause of Abd al-Kader against colonial occupation.', 1844, 8, 6, 1844, 9, 10, 'day', '6 August 1844 – 10 September 1844', 53, 'https://en.wikipedia.org/wiki/Franco-Moroccan_War'),
  ('Q2909602', 'Bombardment of Salé', 'The Bombardment of Salé was a French naval attack against the Moroccan city of Salé that took place between 26 and 27 November 1851. After seven hours of fighting, the Moroccan artillery suffered severe damage, and the French bombarded the city through the night, damaging the city''s infrastructure and the Great Mosque of Salé.', 1851, 11, 26, 1851, 11, 27, 'day', '26 November 1851 – 27 November 1851', 37, 'https://en.wikipedia.org/wiki/Bombardment_of_Sal%C3%A9_(1851)'),
  ('Q1540737', 'Hispano-Moroccan War', 'The Hispano-Moroccan War, also known as the Spanish–Moroccan War, the First Moroccan War, the Tetuán War, or, in Spain, as the War of Africa, was fought from Spain''s declaration of war on Morocco on 22 October 1859 until the Treaty of Wad-Ras on 26 April 1860. It began with a conflict over the borders of the Spanish city of Ceuta and was fought in northern Morocco.', 1859, 10, 22, 1860, 4, 26, 'day', '22 October 1859 – 26 April 1860', 62, 'https://en.wikipedia.org/wiki/Hispano-Moroccan_War_(1859%E2%80%931860)'),
  ('Q11908785', 'Battle of Sierra Bullones', 'The Battle of Sierra de Bullones was the first big battle between Spain and Morocco during the Hispano-Moroccan War.', 1859, 12, 9, NULL, NULL, NULL, 'day', '9 December 1859', 34, 'https://en.wikipedia.org/wiki/Battle_of_Sierra_Bullones'),
  ('Q2888254', 'Battle of Castillejos', 'The Battle of Castillejos was fought on New Year''s Day, 1860, between the Spanish Army of Africa under Leopoldo O''Donnell and the Moroccan Army under Mawlay Abbas in Fnideq (Castillejos) as the Spanish army attempted to capture the cities of Tétouan and Tangier. The Spanish were victorious.', 1860, 1, 1, NULL, NULL, NULL, 'day', '1 January 1860', 41, 'https://en.wikipedia.org/wiki/Battle_of_Castillejos'),
  ('Q2890359', 'Battle of Wad-Ras', 'The Battle of Wad-Ras took place on March 23, 1860 within the Hispano-Moroccan War (1859-1860) that, together with the Battle of Castillejos and Tétouan, completed Spain''s action in North Africa to reduce the hostilities of the Riffian bands against Ceuta.', 1860, 3, 23, NULL, NULL, NULL, 'day', '23 March 1860', 43, 'https://en.wikipedia.org/wiki/Battle_of_Wad_Ras'),
  ('Q4872623', 'Battle of Tétouan', 'The Battle of Tétouan (Arabic: معركة تطوان, Spanish: Batalla de Tetuán) was fought from 4 to 6 February 1860, near Tétouan, Morocco, between a Spanish Army sent to North Africa and the tribal levies which at the time made up the Moroccan Army. The battle was part of the Hispano–Moroccan War of 1859–1860.', 1860, 2, 4, NULL, NULL, NULL, 'day', '4 February 1860', 50, 'https://en.wikipedia.org/wiki/Battle_of_T%C3%A9touan'),
  ('Q9089641', 'Treaty of Wad Ras', 'The Treaty of Wad Ras (Arabic: معاهدة واد راس, Spanish: Tratado de Wad-Ras) was a treaty signed between Morocco and Spain at the conclusion of the War of Tetuan on April 26, 1860, at Wad Ras, located between Tetuan and Tangier. The conditions of the treaty exacerbated Morocco''s defeat in the war, with major concessions being granted to Spain.', 1860, 4, 26, NULL, NULL, NULL, 'day', '26 April 1860', 43, 'https://en.wikipedia.org/wiki/Treaty_of_Wad_Ras'),
  ('Q1806916', 'First Melillan campaign', 'The first Melillan Campaign, also known as the Melilla War or the Margallo War (after Juan García y Margallo, the Spanish governor of Melilla whose defeat and death infuriated the Spanish public) in Spain, was a conflict between Spain and the Riffian tribes of northeastern Morocco, and later the Sultan of Morocco, that began in October 1893, was openly declared November 9, 1893, and was resolved by the Treaty of Fez in 1894.', 1893, 10, 3, 1894, 4, 25, 'day', '3 October 1893 – 25 April 1894', 47, 'https://en.wikipedia.org/wiki/First_Melillan_campaign'),
  ('Q2935421', 'French conquest of Morocco', 'The French conquest of Morocco began with the French Republic occupying the city of Oujda on 29 March 1907. The French launched campaigns against the Sultanate of Morocco which culminated in the signing of the Treaty of Fes and establishment of the French Protectorate in Morocco on 30 March 1912.', 1907, NULL, NULL, 1937, NULL, NULL, 'year', '1907–1937', 56, 'https://en.wikipedia.org/wiki/French_conquest_of_Morocco'),
  ('Q97358280', 'Hafidiya', 'The Hafidiya (Arabic: الحفيظية, romanized: al-Ḥafīẓīya) was a coup d''état in Morocco between 1907 and 1908 in which Abd al-Hafid seized power from his brother Abd al-Aziz. Abd al-Hafid started his movement in Marrakesh in the aftermath of the Algeciras Conference, the French occupation of Oujda and of Casablanca and the gaining the support of Amazigh leaders in the south.', 1907, NULL, NULL, 1908, NULL, NULL, 'year', '1907–1908', 30, 'https://en.wikipedia.org/wiki/Hafidiya'),
  ('Q4871684', 'Battle of Marrakech', 'The Battle of Marrakesh was a central battle in the Hafidiya, in which Abd al-Hafid seized power from his brother Abd al-Aziz, fought outside Marrakesh, Morocco on 19 August 1908. A battalion led by Abd al-Aziz departed from Rabat and was ambushed and defeated on its approach to Marrakesh by forces loyal to Abd al-Hafid.', 1908, 8, 19, NULL, NULL, NULL, 'day', '19 August 1908', 34, 'https://en.wikipedia.org/wiki/Battle_of_Marrakesh'),
  ('Q4872375', 'Battle of Sidi Bou Othman', 'The Battle of Sidi Bou Othman (6 September 1912) was an important battle fought at Sidi Bou Othman, some 40 kilometers north of Marrakesh, during the French conquest of Morocco. It saw the victory of a French column under Colonel Charles Mangin over the forces of the south Moroccan leader Ahmed al-Hiba in September 1912.', 1912, 9, NULL, NULL, NULL, NULL, 'month', 'September 1912', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sidi_Bou_Othman'),
  ('Q16130700', '1912 Fes Anti-Jewish riots', 'The Fes Riots, also known as the Fes Uprising or Mutiny (from Arabic: انتفاضة فاس, Intifadat Fes), the Tritl (Hebrew: התריתל, among the Jewish community) and the Bloody Days of Fes (from French: Les Journées Sanglantes de Fès) were riots which started on April 17, 1912, in Fes, the then-capital of Morocco, when French officers announced the measures of the Treaty of Fes, which created the French protectorate in Morocco. The riots broke out shortly after the population of Fes learnt about the treaty, which they generally viewed as a betrayal by Sultan Abd al-Hafid, who had left Fes for Rabat…', 1912, 4, 17, NULL, NULL, NULL, 'day', '17 April 1912', 47, 'https://en.wikipedia.org/wiki/1912_Fez_riots'),
  ('Q2887939', 'Battle of el-Hri', 'The Battle of El Herri (also known as Elhri) was fought between France and the Berber Zaian Confederation on 13 November 1914. It took place at the small settlement of El Herri, near Khénifra in the French protectorate in Morocco.', 1914, 11, 13, NULL, NULL, NULL, 'day', '13 November 1914', 43, 'https://en.wikipedia.org/wiki/Battle_of_El_Herri'),
  ('Q1138460', 'Battle of Annual', 'The Battle of Annual was fought on 22 July 1921 at Annual, in northeastern Morocco, between the Spanish Army and Riffian Berbers during the Rif War. The Spanish suffered a major military defeat, which is almost always referred to by the Spanish as the Disaster of Annual (Spanish: Desastre de Annual) which is widely considered to be the worst defeat ever suffered by the modern Spanish Army.', 1921, 7, 22, 1921, 8, 9, 'day', '22 July 1921 – 9 August 1921', 61, 'https://en.wikipedia.org/wiki/Battle_of_Annual'),
  ('Q5778556', 'Battle of Abarrán', 'The Battle of Abarrán was a military engagement during the Rif War. It happened when the Spanish established a post in Mountain Abarrán.', 1921, 5, 30, 1921, 6, 1, 'day', '30 May 1921 – 1 June 1921', 37, 'https://en.wikipedia.org/wiki/Battle_of_Abarr%C3%A1n'),
  ('Q104852916', 'Massacre of Monte Arruit', 'The massacre of Monte Arruit took place on 9 August 1921 in Al Aaroui during the Rif War, when, after the July 1921 Battle of Annual, Riffian forces slaughtered most of the Spanish soldiers who had surrendered on that day.', 1921, 7, 29, 1921, 8, 11, 'day', '29 July 1921 – 11 August 1921', 34, 'https://en.wikipedia.org/wiki/Massacre_of_Monte_Arruit'),
  ('Q107331319', 'Siege of Ighriben', 'The siege of Igueriben was a clash between the Rif tribes of Abd el-Krim and the Spanish army, from 16 to July 21, 1921, in the Spanish base of Igueriben where they were besieged by forces of Abd el-Krim. The clash ended with the victory of Abd el-Krim''s forces, wiping out the Spanish contingent.', 1921, 7, 17, 1921, 7, 22, 'day', '17 July 1921 – 22 July 1921', 37, 'https://en.wikipedia.org/wiki/Siege_of_Igueriben'),
  ('Q3273519', 'Naval Battle of Casablanca', 'The Naval Battle of Casablanca was a series of naval engagements fought between American ships covering the invasion of North Africa and Vichy French ships defending the neutrality of French Morocco in accordance with the Second Armistice at Compiègne during World War II. Allied military planners anticipated an all-American force assigned to seize the Atlantic port city of Casablanca might be greeted as liberators. An invasion task force of 102 American ships carrying 35,000 American soldiers approached the Moroccan coast undetected under cover of darkness.', 1942, 11, 8, 1942, 11, 16, 'day', '8 November 1942 – 16 November 1942', 51, 'https://en.wikipedia.org/wiki/Naval_Battle_of_Casablanca'),
  ('Q4872084', 'Battle of Port Lyautey', 'The Battle of Port Lyautey began on 8 November 1942 for the city of Port Lyautey, today known as Kenitra, in French Morocco. The battle ended with its capture and occupation by American troops, overrunning French forces after more than two days of fierce fighting.', 1942, 11, 8, NULL, NULL, NULL, 'day', '8 November 1942', 34, 'https://en.wikipedia.org/wiki/Battle_of_Port_Lyautey'),
  ('Q8187830', 'Treaty of Angra de Cintra', 'The Treaty of Angra de Cintra, signed by Spain and Morocco on 1 April 1958, ended the Spanish protectorate in Morocco and helped end the Ifni War. The Spanish foreign minister, Fernando María Castiella y Maíz, and his Moroccan counterpart, Ahmed Balafrej, as well as their respective secretaries, met on the Bay of Cintra in the Spanish colony of Río de Oro between 31 March and 2 April in utmost secrecy to negotiate an end to the clashes between Spain and Moroccan-supported rebels that had begun in October 1957.', 1958, 4, 2, NULL, NULL, NULL, 'day', '2 April 1958', 34, 'https://en.wikipedia.org/wiki/Treaty_of_Angra_de_Cintra'),
  ('Q698056', '1960 Agadir earthquake', 'The 1960 Agadir earthquake occurred on 29 February at 23:40:18 Western European Time near the city of Agadir, located in western Morocco on the shore of the Atlantic Ocean. Despite the earthquake''s moderate Mw scale magnitude of 5.8, its relatively shallow depth (15.0 km) resulted in strong surface shaking, with a maximum perceived intensity of X (Extreme) on the Mercalli intensity scale.', 1960, 2, 29, NULL, NULL, NULL, 'day', '29 February 1960', 65, 'https://en.wikipedia.org/wiki/1960_Agadir_earthquake'),
  ('Q4851214', 'Years of Lead (Marocco)', 'The Years of Lead (Arabic: سنوات الرصاص, romanized: Sanawāt ar-Raṣāṣ) was a period of the rule of King Hassan II of Morocco, from roughly the 1960s to the 1980s, marked by state violence and repression against political dissidents and activists from across the political spectrum.', 1960, NULL, NULL, 2000, NULL, NULL, 'decade', '1960s – 2000s', 43, 'https://en.wikipedia.org/wiki/Years_of_Lead_(Morocco)'),
  ('Q1891008', 'Sand War', 'The Sand War (Arabic: حَرْبُ الرِّمَال, romanized: Ḥarb ar-Rimāl) was a border conflict between Algeria and Morocco fought from September 25 to October 30, 1963, although a formal peace treaty was not signed until February 20, 1964. It resulted largely from the Moroccan government''s claim to portions of Algeria''s Tindouf and Béchar provinces.', 1963, 9, 25, 1964, 2, 20, 'day', '25 September 1963 – 20 February 1964', 63, 'https://en.wikipedia.org/wiki/Sand_War'),
  ('Q116179236', 'Casablanca Protocol', 'The Casablanca Protocol, formally the Protocol for the Treatment of Palestinians in Arab States, was a statement by the Arab League on 11 September 1965, made at the 1965 Arab League summit in Casablanca, Morocco. The statement, in five articles, sought to regularize the legal protections for Palestinian refugees residing in the countries of the Arab World.', 1965, 9, 11, NULL, NULL, NULL, 'day', '11 September 1965', 26, 'https://en.wikipedia.org/wiki/Casablanca_Protocol'),
  ('Q3510571', '1969 Portugal earthquake', 'The 1969 Portugal earthquake struck western Portugal and Morocco on 28 February at 02:40 UTC. Originating west of the Strait of Gibraltar, the earthquake registered a magnitude of 7.8 and the maximum felt intensity was VII (Very strong) on the Mercalli intensity scale. In total, 13 people died and 80 sustained minor injuries.', 1969, 2, 28, NULL, NULL, NULL, 'day', '28 February 1969', 39, 'https://en.wikipedia.org/wiki/1969_Portugal_earthquake'),
  ('Q28176532', 'Moulay Bouazza plot', 'The Moulay Bouazza plot was a 1973 conspiracy by members of the National Union of Popular Forces to overthrow King Hassan II of Morocco.', 1973, NULL, NULL, NULL, NULL, NULL, 'year', '1973', 30, 'https://en.wikipedia.org/wiki/Moulay_Bouazza_plot'),
  ('Q870684', 'Green March', 'The Green March (Arabic: المسيرة الخضراء, romanized: al-masīrat ul-khaḍrāʾ) was a strategic mass demonstration in November 1975, coordinated by the Moroccan government and the military, to force Spain to hand over the disputed, autonomous semi-metropolitan province of Spanish Sahara to Morocco. The Spanish government was preparing to abandon the territory as part of the decolonization of Africa, just as it had granted independence to Equatorial Guinea in 1968.', 1975, 11, 6, 1975, 11, 9, 'day', '6 November 1975 – 9 November 1975', 66, 'https://en.wikipedia.org/wiki/Green_March'),
  ('Q4690967', 'Agadir air disaster', 'On 3 August 1975, a chartered Royal Air Maroc international passenger flight from Paris to Agadir crashed into a mountain while descending to land at Inezgane Airport. All 188 passengers and crew members died.', 1975, 8, 3, NULL, NULL, NULL, 'day', '3 August 1975', 51, 'https://en.wikipedia.org/wiki/1975_Agadir_Royal_Air_Maroc_Boeing_707_crash'),
  ('Q2888145', 'Battle of Bir Anzarane', 'The Battle of Bir Anzarane was a significant military confrontation between the armed forces of the Sahrawi Arab Democratic Republic, represented by the Polisario Front, and the Moroccan Armed Forces. The confrontation took place in the oasis of Bir Anzarane, situated in Western Sahara, a territory that is the subject of a claim by both parties.', 1979, 8, 11, NULL, NULL, NULL, 'day', '11 August 1979', 34, 'https://en.wikipedia.org/wiki/Battle_of_Bir_Anzarane_(1979)'),
  ('Q12243725', 'Arabic–African Union Treaty', 'The Oujda Treaty (also known as the Arab–African Federation Treaty) was signed on 13 August 1984 between King Hassan II of Morocco and Muammar Gaddafi of Libya. It was approved by Moroccan voters in a referendum on 31 August, and by the Libyan General People''s Congress.', 1984, 8, 13, NULL, NULL, NULL, 'day', '13 August 1984', 34, 'https://en.wikipedia.org/wiki/Oujda_Treaty'),
  ('Q4871159', 'Battle of Guelta Zemmour', 'The Battle of Guelta Zemmur occurred on 7 October 1989, when POLISARIO guerrillas commanded by Lahbib Ayub attacked the village of Guelta Zemmur on the Moroccan side of the Moroccan Western Sahara Wall. The attack was the first major military engagement in the war since 1988, as the Polisario Front had ended negotiations with Morocco in that year.', 1989, 10, 7, NULL, NULL, NULL, 'day', '7 October 1989', 34, 'https://en.wikipedia.org/wiki/Battle_of_Guelta_Zemmur_(1989)'),
  ('Q4115048', '2004 Morocco earthquake', 'On 24 February 2004 at 03:27 CET (02:27 UTC), an earthquake with a moment magnitude of 6.3 and maximum Mercalli intensity of IX (Violent) struck Morocco''s Al Hoceïma Province. The earthquake''s epicenter was located about 13 km (8.1 mi) south-southwest of the provincial capital of Al Hoceima.', 2004, 2, 24, NULL, NULL, NULL, 'day', '24 February 2004', 50, 'https://en.wikipedia.org/wiki/2004_Al_Hoceima_earthquake'),
  ('Q1144666', '2011–2012 Moroccan protests', 'The Moroccan protests were a series of demonstrations across Morocco which occurred from 20 February 2011 to the fall of 2012. They were part of the larger Arab Spring protests.', 2011, 2, 20, NULL, NULL, NULL, 'day', '20 February 2011', 61, 'https://en.wikipedia.org/wiki/2011%E2%80%932012_Moroccan_protests'),
  ('Q2641872', '2011 Royal Moroccan Air Force Lockheed C-130 Hercules crash', 'On 26 July 2011, a C-130 Hercules military transport aircraft operated by the Royal Moroccan Air Force crashed near Guelmim, Morocco, killing all 80 people on board. The plane was carrying 71 passengers (initially reported as 72), mostly members of the Moroccan Armed Forces, and nine crew.', 2011, 7, 26, NULL, NULL, NULL, 'day', '26 July 2011', 47, 'https://en.wikipedia.org/wiki/2011_Royal_Moroccan_Air_Force_C-130_crash'),
  ('Q255997', 'Houthi insurgency', 'The Houthi insurgency, also known as the Sa''dah Wars, was a military rebellion pitting Zaidi Shia Houthis that began in northern Yemen and has since escalated into a full-scale civil war. The conflict was sparked in 2004 by the government''s attempt to arrest Hussein al-Houthi, a Zaidi religious leader of the Houthis and a former parliamentarian on whose head the government had placed a $55,000 bounty.', 2015, 2, 6, NULL, NULL, NULL, 'day', '6 February 2015', 63, 'https://en.wikipedia.org/wiki/Houthi_insurgency'),
  ('Q22281586', '2016 Strait of Gibraltar earthquake', 'The 2016 Alboran Sea earthquake struck offshore, north northeast of Al Hoceïma, Morocco in the Strait of Gibraltar on 25 January at 04:22:02 UTC, or roughly 05:22:02 West Africa Time. At its strongest in the Alboran Sea, the earthquake measured 6.3–6.4 on the moment magnitude scale (Mw) at a shallow hypocenter depth of 12 km (7.5 mi).', 2016, 1, 25, NULL, NULL, NULL, 'day', '25 January 2016', 34, 'https://en.wikipedia.org/wiki/2016_Alboran_Sea_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q101559356', 'Western Saharan clashes (2020–present)', 'Clashes between Morocco and the Polisario Front''s Sahrawi Arab Democratic Republic (SADR) broke out in the disputed region of Western Sahara in November 2020. It was the latest escalation of an unresolved conflict over the region, of which 75–80% is occupied by Morocco.', 2020, 11, 13, NULL, NULL, NULL, 'day', '13 November 2020', 51, 'https://en.wikipedia.org/wiki/Western_Saharan_clashes_(2020%E2%80%93present)'),
  ('Q112725255', '2022 Melilla incident', 'On 24 June 2022, 23 migrants and asylum seekers were killed after a crowd crush at the Melilla border fence during a conflict with Moroccan and Spanish security forces. The conflict broke out as around 2,000 migrants and asylum seekers gathered in the early hours of the day to cross the border into Spain.', 2022, 6, 24, NULL, NULL, NULL, 'day', '24 June 2022', 53, 'https://en.wikipedia.org/wiki/2022_Melilla_border_incident'),
  ('Q122351413', '2023 Marrakesh-Safi earthquake', 'On 8 September 2023 at 23:11 DST (22:11 UTC), an earthquake with a moment magnitude of 6.9 and maximum Mercalli intensity of IX (Violent) struck Morocco''s Al Haouz Province. The earthquake''s epicenter was 73.4 km (45.6 mi) southwest of Marrakesh, near the town of Ighil and the Oukaïmeden ski resort in the Atlas Mountains.', 2023, 9, 8, NULL, NULL, NULL, 'day', '8 September 2023', 78, 'https://en.wikipedia.org/wiki/2023_Al_Haouz_earthquake'),
  ('Q136399532', '2025 protests in Morocco', 'A series of youth-led demonstrations took place in Morocco between 27 September and 18 October 2025. Organized by decentralized, anonymous collectives known as GenZ 212 and Moroccan Youth Voice (Arabic: صوت شباب المغرب, romanized: ṣawt šabāb al-Maḡrib), the protests demanded significant improvements to public education and healthcare, while criticizing government focus on international sporting events like the 2030 FIFA World Cup and the 2025 Africa Cup of Nations.', 2025, 9, 27, 2025, 10, 18, 'day', '27 September 2025 – 18 October 2025', 47, 'https://en.wikipedia.org/wiki/2025_Moroccan_Gen_Z_protests');
